using System.Text.Json;
using Microsoft.AspNetCore.Mvc; using RaceDay.MvC.Models; using RaceDay.MvC.Services;
namespace RaceDay.MvC.Controllers;
public class ProfileController(RaceDayApiClient api):Controller { private bool SignedIn=>HttpContext.Session.GetInt32("UserID")!=null; public async Task<IActionResult> Index(){if(!SignedIn)return RedirectToAction("Login","Account");var r=await api.Get<ProfileViewModel>("api/users/me");if(!r.Ok){ViewBag.Error=r.Error;return View(new ProfileViewModel());}return View(r.Data);} [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> Index(ProfileViewModel m){if(!SignedIn)return RedirectToAction("Login","Account");if(!ModelState.IsValid)return View(m);var r=await api.Send<ProfileViewModel>(HttpMethod.Put,"api/users/me",new{m.FirstName,m.LastName,m.PhoneNumber});if(!r.Ok){ModelState.AddModelError("",r.Error??"Update failed.");return View(m);}TempData["Success"]="Profile updated.";return View(r.Data);} [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> UploadPicture(IFormFile file){if(!SignedIn)return RedirectToAction("Login","Account");if(file is null){TempData["Error"]="Select an image first.";return RedirectToAction(nameof(Index));}var r=await api.SendFile<JsonElement>("api/users/me/profile-picture",file);TempData[r.Ok?"Success":"Error"]=r.Error??(r.Ok?"Profile picture uploaded.":"Could not upload profile picture.");return RedirectToAction(nameof(Index));} public async Task<IActionResult> Picture(){if(!SignedIn)return Unauthorized();var r=await api.GetFile("api/users/me/profile-picture");return r.Ok&&r.Data is not null?File(r.Data,r.ContentType??"image/jpeg"):NotFound();} }